import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第二卷 回潮 · 第33章 中秋","description":"","frontmatter":{},"headers":[],"relativePath":"第33章_中秋.md","filePath":"第33章_中秋.md"}'),r={name:"第33章_中秋.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第二卷-回潮-·-第33章-中秋" tabindex="-1">第二卷 回潮 · 第33章 中秋 <a class="header-anchor" href="#第二卷-回潮-·-第33章-中秋" aria-label="Permalink to &quot;第二卷 回潮 · 第33章 中秋&quot;">​</a></h1><p>放假前最后一节课后，教室空得很快。</p><p>江苒收包收到一半，抬头看我，没说话。我们冷了两天了，起因是一张纸条。顾远闹着抽走我写了一半的东西，当众念了一句，陈默跟着笑。她当场转过脸，说我什么都藏，连一句当面的话都不肯给。我慢了一拍，没接住。</p><p>她把包带一提，铃铛响了一声。</p><p>“中秋各回各家，你好好过。”</p><p>我说好。她走出门，风把她桌角那颗没折完的纸星星吹到我桌上，淡黄色的，瘪着一角。我把它攥进口袋。</p><p>校门口人很多，林小满拉着何晓去买橘子汽水，秦浩抱着球不撒手，他们还在争月饼的馅。叶老师站在走廊上说假后见。我穿过这片热闹，坐车回了雾河边。</p><p>白天家里很忙，我帮奶奶把窗帘卷起来抱到阳台拍灰，灰尘在阳光里飞起来，鼻尖发痒，打了好几个喷嚏。奶奶笑我慢手慢脚，塞给我一块刚切好的月饼皮让我尝甜。午后和她一起理老唱片，唱片套沾着潮味，指尖一抹就是薄尘。爸把米和芝麻花生拌在一起，手上沾满糯米粉，笑着让我尝馅甜不甜。妈在厨房里蒸米糕，热气一股股涌出来，窗玻璃很快蒙上一层白雾。我站在门口看水珠慢慢滑下来，心里却静不下来，口袋里那颗瘪角的纸星星被我摸得发热，掌心也跟着发潮。我去院角把晾着的被单收进来，布面晒得暖烘烘的，抱在怀里有阳光的燥香，又把桌上的月饼一个个摆进盘子，盘沿磕出轻响，指尖沾着油纸的甜腻，鼻尖全是芝麻香。想起在教室里她转过去的侧脸，那点凉一下子就回来了，热闹里反而更静。</p><p>宋阿婆坐在门口剥枇杷，汁水沾在指尖上，香很淡。她见我耷拉着脸，塞给我一颗海盐糖，咸甜的，说败火。我在她旁边坐下，听剪刀开合的轻响，看筐里的皮一点点堆高，心里那团燥，一点点被晚风吹薄。她又递我一小杯热水，杯壁烫手，我捧着小口喝，甜咸混着热气往胸口走，倒把那点闷顶松了些。</p><p>晚上家里蒸米糕，芝麻花生馅，粘牙。爸翻出一张老唱片放上，沙沙的底噪里，有人慢悠悠唱潮水。妈问学校好不好，我说好。嘴上说好，心里全是江苒转过去的侧脸。</p><p>月亮上来后，我走到院子里，给她打电话。</p><p>我先把碗筷收去厨房，用热水把手洗干净，又用毛巾把指尖擦干，才摸出那张写着她家电话的小纸条。纸条被我叠得方方正正，打开时指尖有点抖，我把它平铺在桌角，照着数字一个个拨过去。话筒拿起又放下，放下又拿起，听筒里细细的电流声像远处的河，一下一下撞着耳朵。我深吸一口气，把外套披上，推开门往堤边走，夜风灌进领口，凉凉的贴着脖子，脚下的草叶沾着露水，踩上去软软的，空气里桂花的甜混着河泥的腥，一甜一凉，让人既想快走又想慢下来。</p><p>响了很久，那边才接。</p><p>“喂。”她声音轻轻的。</p><p>“是我。”我说。</p><p>“知道。”她顿了顿，“你那边，有河水声吗。”</p><p>我把手机往堤的方向偏了偏，风里果然有水声，细细的，推着走。</p><p>“听到了吗。”我问。</p><p>“听到了。”她说，“我这边只有切月饼的声音。”</p><p>僵着的那点东西，被水声泡软了些。</p><p>“你没折完的那颗，在我这。”我说，“我捏好了，鼓起来了。加上之前的，正好第七颗。我刚才数了数，一共七颗。”</p><p>她那边静了几秒，有纸摩擦的轻响。</p><p>“沈聿，我没气顾远。”她低声说，“我气你不说。你纸上写那么多，当面倒一个字也没有。”她顿了一下，又补了一句，声音软软的：“你这个人啊，纸上倒敢写，见面就哑了。”这话不带新事，只是把我的毛病点在灯下，我听得耳朵发热，却也觉得被她看穿得很安稳。想起在连廊里她也这样说过我一次，那时我也是半天接不上话，只会把纸条攥得更紧。</p><p>我摩挲着那颗星星，尖角硌着指腹。</p><p>“我说话慢，一急就乱。写字快些。”</p><p>“我知道你慢。”她叹气，“我一快，就怕把你丢下。”</p><p>心口像喝了一口薄荷水，又凉又醒。</p><p>“我以后走快点，你走慢点，我们在中间碰头。”我说。</p><p>她笑了，铃铛似的。</p><p>“纸条的事，原谅你了。中秋晚上，不许藏了，要说出来。”</p><p>我抬头看月亮，又圆又亮，像泡在水里。院角有桂花香，混着米糕的甜。热水喝到舌根是烫的，桂花闻到鼻尖是甜的，两种感觉裹在一起，倒把紧张泡薄了些。</p><p>“江苒，中秋快乐。”我说，“从校门口到河堤，我一路都在想你。”</p><p>那边安静了一会儿，才很小声回：“我也想你，比你多一点。”</p><p>耳朵一下烫起来。我赶紧问她吃了什么馅，她说莲蓉，太甜，灌了两口薄荷水。我说我家粘牙的，她笑我说话要被粘住。</p><p>唱针滑到尽头，沙沙响了一阵就停了，院子静下来，只剩河水声。</p><p>“你去河边吧。”她忽然说，“我去阳台，开着电话，一起看月亮。”</p><p>我披上外套往堤上走。露水洇湿鞋面，草腥混着泥味。站上堤，雾河一下铺开，满河月光碎成小块，又聚拢，像谁撒了一把碎光，又一点点捡回去。潮气贴着小腿往上爬，带着水草的凉。我把外套拉紧些，电话贴着耳朵，她的呼吸混着水声，一下就觉得两岸离得很近。</p><p>“河里有月亮，你呢。”我问。</p><p>“我阳台只能看到小小一块。”她说，“你的大，替我多看一眼。”</p><p>我扔了颗小石子下去，水纹荡开，凉汽扑到脸上。</p><p>“第七颗放哪了。”她问。</p><p>“放心口的口袋。”我说，“回去给你。第八颗一起折。”</p><p>“电话里拉钩不算，回来补上。”</p><p>“好，用星星盖章。”</p><p>她笑了一阵，又轻下去：“沈聿，我阳台上也折了一颗，也是第七颗，我们折重了。”</p><p>我看着河面，心口那颗像热起来。</p><p>“那就两颗第七颗，凑一对。一颗放你那，一颗放我这。”</p><p>我把话筒换到另一只手，用肩膀夹住，空出的手去摸口袋里的星星，星角硌着指腹，热水杯的余温还在手背上，一烫一凉，手倒不抖了。风大起来，水声一下一下，很稳。我握着话筒想回她那句“你这个人啊”，嘴张了几次，喉咙却像被热水烫住，发不出完整的句子，只听见自己呼吸变长，贴在话筒上闷闷的。她那边轻轻喂了一声，我还是答不上来，耳朵烫得厉害，心里明白她在等我一句服软，可话到嘴边只剩一团热气。那一下的卡住，比平常写纸条时卡壳还难受，也让刚才和好的暖多了一点真实的酸。</p><p>月光落在河面，也落在我手背上。我想，此刻她阳台的栏杆上，应该也落着同一片光。</p><p>谁也不舍得先挂。沉默里，只有呼吸和水声。</p><p>快说晚安时，她忽然压低声音：“沈聿，你听，河水里是不是有铃铛声。”</p><p>我屏住呼吸，朝月光正中看去。水面晃着一小片亮，像什么东西顺着潮，正朝我漂过来。</p>',52)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
